func Table(rows [][]string) string {
	if len(rows) == 0 {
		return ""
	}
	widths := make([]int, len(rows[0])) // max width per column
	for _, row := range rows {
		for c, cell := range row {
			if len(cell) > widths[c] {
				widths[c] = len(cell)
			}
		}
	}
	var b strings.Builder
	for _, row := range rows {
		for c, cell := range row {
			// %-*s left-aligns cell in widths[c] columns
			fmt.Fprintf(&b, "%-*s ", widths[c], cell)
		}
		b.WriteByte('\n')
	}
	return b.String()
}

type Duration int // seconds

// String satisfies fmt.Stringer, so %v and %s use it.
func (d Duration) String() string {
	total := int(d)
	h := total / 3600
	m := (total % 3600) / 60
	s := total % 60
	// %02d zero-pads each field to two digits.
	return fmt.Sprintf("%02d:%02d:%02d", h, m, s)
}

func main() {
	d := Duration(3661)
	fmt.Printf("%v\n", d) // 01:01:01
	fmt.Println(d.String())
}
